/* Tullock contest simulator (two players), computed in the browser in a few milliseconds.
 * The same algorithm as src/tullock/contest.py; tests/test_js_parity.py keeps the two in step.
 *
 * Embed:  <div class="tullock-sim" data-zip="https://.../tullock-sim-{lang}.zip"></div>
 *         plus `tullock_sim: true` in the post front matter (head.ejs then loads /js/tullock-sim.js).
 *         Do not put a raw <script> in the post body: kramed swallows everything after it.
 * Math on the page is typeset by the page's MathJax; the downloadable figure carries its labels as
 * plain paths (TS_LABELS, made by scripts/make_labels.py).
 */
(() => {
  // ---------------------------------------------------------------- model
  const GRID = 200
  const INV_PHI = (Math.sqrt(5) - 1) / 2
  const AXIS = 100 // the drawing always spans 0..AXIS, so changing V or c visibly moves things
  const PAY = 50 // the payoff tab spans -PAY..PAY

  function run(V, c, r, points = 161) {
    const hi = V / c
    const win = (a, b) => {
      const t = a ** r + b ** r
      return t === 0 ? 0.5 : a ** r / t
    }
    const pay = (own, other) => V * win(own, other) - c * own

    // best response to the rival's expenditure: coarse grid, then golden section around the best cell
    const br = (other) => {
      const f = (t) => pay(t, other)
      const step = hi / GRID
      let k = 0, best = -Infinity
      for (let j = 0; j <= GRID; j++) {
        const v = f(j * step)
        if (v > best) { best = v; k = j }
      }
      let a = Math.max(0, (k - 1) * step), b = Math.min(hi, (k + 1) * step)
      for (let i = 0; i < 80 && b - a >= 1e-12 * Math.max(1, hi); i++) {
        const m1 = b - INV_PHI * (b - a), m2 = a + INV_PHI * (b - a)
        if (f(m1) < f(m2)) a = m1
        else b = m2
      }
      const x = (a + b) / 2
      return f(x) >= f(0) ? x : 0
    }

    // let each player best-respond in turn (damped), starting from an asymmetric point
    const x = [hi / 6, hi / 3]
    let converged = false, iterations = 500
    for (let it = 1; it <= 500; it++) {
      let move = 0
      for (let i = 0; i < 2; i++) {
        const next = 0.5 * x[i] + 0.5 * br(x[1 - i])
        move = Math.max(move, Math.abs(next - x[i]))
        x[i] = next
      }
      if (move < 1e-6 * hi) { converged = true; iterations = it; break }
    }

    const xs = Array.from({ length: points }, (_, k) => (hi * k) / (points - 1))
    return {
      params: { V, c, r },
      curve: { x: xs, br: xs.map(br) },
      // player 1's payoff as x1 varies while player 2 stays at the equilibrium value
      payoffCurve: converged ? { x: xs, pi: xs.map((t) => pay(t, x[1])) } : null,
      equilibrium: { x, converged, iterations },
      closedForm: r <= 2 ? (r * V) / (4 * c) : null,
      winProb: [win(x[0], x[1]), win(x[1], x[0])],
      payoff: [pay(x[0], x[1]), pay(x[1], x[0])],
      dissipation: (c * (x[0] + x[1])) / V,
      demoWinProb: win(60, 40),
    }
  }

  if (typeof module !== 'undefined') module.exports = { run }
  if (typeof document === 'undefined') return

  // ---------------------------------------------------------------- drawing
  // A figure is described once, as SVG elements plus label slots, and drawn twice: on the page
  // (labels are HTML, typeset by MathJax) and in the download (labels are TS_LABELS paths).
  const W = 400, H = 400, M = 36
  const LABELS = typeof TS_LABELS !== 'undefined' ? TS_LABELS : {}

  const mapX = (v) => M + (v / AXIS) * (W - 2 * M)
  const mapY = (v) => H - M - (v / AXIS) * (H - 2 * M)
  const mapP = (v) => H / 2 - (v / PAY) * (H / 2 - M)

  // a polyline that is cut where `cut(i)` says the curve jumps between point i-1 and i
  function polylines(pts, cut, attrs) {
    const parts = []
    let cur = []
    pts.forEach((p, i) => {
      if (i && cut(i)) { parts.push(cur); cur = [] }
      cur.push(p)
    })
    parts.push(cur)
    return parts
      .filter((q) => q.length > 1)
      .map((q) => `<polyline points="${q.map((p) => `${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(' ')}" fill="none" stroke="currentColor"${attrs}/>`)
      .join('')
  }

  const axes = (y0, yBottom) =>
    `<path d="M${M} ${y0}H${W - M + 14}M${M} ${yBottom}V${M - 14}" fill="none" stroke="currentColor" stroke-width="1.2"/>` +
    `<path d="M${W - M + 14} ${y0}l-7 -3.5v7zM${M} ${M - 14}l-3.5 7h7z" fill="currentColor"/>`

  const DASH = ' stroke-dasharray="4 3"'
  const dotted = (x, y, x0, y0) => `<path d="M${x} ${y}V${y0}M${x} ${y}H${x0}" fill="none" stroke="currentColor" stroke-width="1" stroke-dasharray="1 3" opacity="0.7"/>`

  const LEG = {
    br: [{ key: 'br1', tex: '$x_1 = BR_1(x_2)$', dash: '' }, { key: 'br2', tex: '$x_2 = BR_2(x_1)$', dash: DASH }],
    pay: [{ key: 'pil', tex: '$\\pi_1(x_1, x_2^*)$', dash: '' }],
  }

  function figureBR(s) {
    const { V, c } = s.params, vc = V / c, eq = s.equilibrium
    const { x: xs, br } = s.curve
    const cut = (i) => (br[i] === 0) !== (br[i - 1] === 0) && Math.abs(br[i] - br[i - 1]) > 0.03 * AXIS
    const els = [
      axes(H - M, H - M),
      `<path d="M${mapX(vc)} ${H - M - 3}v6M${M - 3} ${mapY(vc)}h6" fill="none" stroke="currentColor" stroke-width="1"/>`,
      polylines(xs.map((t, i) => [mapX(br[i]), mapY(t)]), cut, ' stroke-width="1.6"'),
      polylines(xs.map((t, i) => [mapX(t), mapY(br[i])]), cut, ` stroke-width="1.6"${DASH}`),
    ]
    const labels = [
      { id: 'x1', key: 'x1', tex: '$x_1$', x: W - M + 20, y: H - M, ax: 0, ay: 0.5 },
      { id: 'x2', key: 'x2', tex: '$x_2$', x: M, y: M - 20, ax: 0.5, ay: 1 },
      { id: 'zero', key: 'zero', tex: '$0$', x: M - 6, y: H - M + 5, ax: 1, ay: 0 },
      { id: 'vcx', key: 'vc', tex: '$\\dfrac{V}{c}$', x: mapX(vc), y: H - M + 7, ax: 0.5, ay: 0 },
      { id: 'vcy', key: 'vc', tex: '$\\dfrac{V}{c}$', x: M - 8, y: mapY(vc), ax: 1, ay: 0.5 },
    ]
    if (eq.converged) {
      const [a, b] = eq.x
      els.push(dotted(mapX(a), mapY(b), M, H - M))
      els.push(`<circle cx="${mapX(a)}" cy="${mapY(b)}" r="5" class="ts-dot"/>`)
      labels.push({ id: 'x1s', key: 'x1s', tex: '$x_1^*$', x: mapX(a), y: H - M + 5, ax: 0.5, ay: 0 })
      labels.push({ id: 'x2s', key: 'x2s', tex: '$x_2^*$', x: M - 7, y: mapY(b), ax: 1, ay: 0.5 })
    }
    return { els: els.join(''), labels, legend: LEG.br }
  }

  function figurePay(s) {
    const eq = s.equilibrium, y0 = H / 2
    const els = [axes(y0, H - M)]
    const labels = [
      { id: 'x1', key: 'x1', tex: '$x_1$', x: W - M + 20, y: y0, ax: 0, ay: 0.5 },
      { id: 'pi1', key: 'pi1', tex: '$\\pi_1$', x: M, y: M - 20, ax: 0.5, ay: 1 },
      { id: 'zero', key: 'zero', tex: '$0$', x: M - 6, y: y0 + 5, ax: 1, ay: 0 },
    ]
    if (s.payoffCurve) {
      const { x: xs, pi } = s.payoffCurve
      const cut = (i) => Math.abs(pi[i]) > PAY || Math.abs(pi[i - 1]) > PAY
      els.push(polylines(xs.map((t, i) => [mapX(t), mapP(Math.max(-PAY, Math.min(PAY, pi[i])))]), cut, ' stroke-width="1.6"'))
      const a = eq.x[0], p = s.payoff[0]
      els.push(dotted(mapX(a), mapP(p), M, y0))
      els.push(`<circle cx="${mapX(a)}" cy="${mapP(p)}" r="5" class="ts-dot"/>`)
      labels.push({ id: 'x1s', key: 'x1s', tex: '$x_1^*$', x: mapX(a), y: y0 + 5, ax: 0.5, ay: 0 })
      labels.push({ id: 'pi1s', key: 'pi1s', tex: '$\\pi_1^*$', x: M - 7, y: mapP(p), ax: 1, ay: 0.5 })
    }
    return { els: els.join(''), labels, legend: LEG.pay }
  }

  const FIGURE = { br: figureBR, pay: figurePay }

  // ---------------------------------------------------------------- download
  // The figure you download is its own SVG in the bw-math-diagrams style: black lines, transparent
  // background, arrow axes, every label LaTeX-set, no font and no MathJax needed. PNG is that SVG
  // drawn on a white canvas; PDF is made from it by jsPDF + svg2pdf.js, loaded only when asked.
  const K = 1.2
  const EW = 410, EH = 412
  const FILE = { br: 'tullock-best-response', pay: 'tullock-payoff' }

  function exportSvg(s, mode) {
    const fig = FIGURE[mode](s)
    const out = [fig.els.replace(/class="ts-dot"/g, 'fill="currentColor"')]
    const lab = (key, x, y, ax, ay, k = K) => {
      const l = LABELS[key]
      if (l) out.push(`<g fill="currentColor" transform="translate(${(x - ax * l.w * k).toFixed(2)} ${(y - ay * l.h * k).toFixed(2)}) scale(${k})">${l.body}</g>`)
    }
    for (const l of fig.labels) lab(l.key, l.x, l.y, l.ax, l.ay)
    fig.legend.forEach((e, i) => {
      const l = LABELS[e.key] || { w: 0 }
      const y = 20 + i * 24
      const x0 = EW - 6 - l.w * 1.1
      out.push(`<path d="M${x0 - 36} ${y}h28" fill="none" stroke="currentColor" stroke-width="1.6"${e.dash}/>`)
      lab(e.key, x0, y, 0, 0.5, 1.1)
    })
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${EW} ${EH}" width="${EW}" height="${EH}" color="#000">${out.join('')}</svg>`
  }

  function save(blob, name) {
    const url = URL.createObjectURL(blob)
    const a = Object.assign(document.createElement('a'), { href: url, download: name })
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    setTimeout(() => URL.revokeObjectURL(url), 10000)
  }

  function svgToPng(svg, scale = 3) {
    const sized = svg.replace(`width="${EW}" height="${EH}"`, `width="${EW * scale}" height="${EH * scale}"`)
    const url = URL.createObjectURL(new Blob([sized], { type: 'image/svg+xml;charset=utf-8' }))
    return new Promise((ok, no) => {
      const img = new Image()
      img.onload = () => {
        const cv = Object.assign(document.createElement('canvas'), { width: EW * scale, height: EH * scale })
        const ctx = cv.getContext('2d')
        ctx.fillStyle = '#fff'
        ctx.fillRect(0, 0, cv.width, cv.height)
        ctx.drawImage(img, 0, 0, cv.width, cv.height)
        cv.toBlob((b) => (b ? ok(b) : no(new Error('png'))), 'image/png')
      }
      img.onerror = () => no(new Error('svg image'))
      img.src = url
    }).finally(() => URL.revokeObjectURL(url))
  }

  const loadScript = (src) => new Promise((ok, no) => {
    if (document.querySelector(`script[src="${src}"]`)) return ok()
    document.head.appendChild(Object.assign(document.createElement('script'), { src, onload: ok, onerror: no }))
  })

  async function svgToPdf(svg) {
    await loadScript('https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js')
    await loadScript('https://cdn.jsdelivr.net/npm/svg2pdf.js@2.2.4/dist/svg2pdf.umd.min.js')
    const w = EW * 0.75, h = EH * 0.75
    const holder = Object.assign(document.createElement('div'), { innerHTML: svg })
    holder.style.cssText = 'position:fixed;left:-9999px;top:0'
    document.body.appendChild(holder)
    try {
      const doc = new window.jspdf.jsPDF({ unit: 'pt', format: [w, h], orientation: w > h ? 'l' : 'p' })
      await doc.svg(holder.firstElementChild, { x: 0, y: 0, width: w, height: h })
      return doc.output('blob')
    } finally {
      holder.remove()
    }
  }

  async function download(svg, mode, format) {
    const name = `${FILE[mode]}.${format}`
    if (format === 'svg') save(new Blob([svg], { type: 'image/svg+xml;charset=utf-8' }), name)
    else if (format === 'png') save(await svgToPng(svg), name)
    else save(await svgToPdf(svg), name)
  }
  window.__tullockExport = { run, exportSvg, download, svgToPng, svgToPdf }

  // ---------------------------------------------------------------- page
  const LANG = (document.documentElement.lang || 'zh').toLowerCase().startsWith('zh') ? 'zh' : 'en'
  const T = {
    zh: {
      V: '獎勵 $V$', c: '單位成本 $c$', r: '實力差距參數 $r$',
      eq: '數值均衡 $(x_1^*, x_2^*)$', cf: '公式 $x^* = \\frac{rV}{4c}$', p: '均衡勝率 $(p_1^*, p_2^*)$',
      pay: '均衡預期報酬 $(\\pi_1^*, \\pi_2^*)$', diss: '租金耗散率 $D$', demo: '$x_1 = 60,\\ x_2 = 40$ 時的 $p_1$',
      warn: '迭代沒有收斂：$r > 2$ 時沒有純策略均衡。',
      tabBr: '最佳反應', tabPay: '預期報酬',
      zip: '下載 Python 程式碼 (.zip)', dl: '下載圖形',
    },
    en: {
      V: 'Prize $V$', c: 'Unit cost $c$', r: 'Skill-gap parameter $r$',
      eq: 'Numeric equilibrium $(x_1^*, x_2^*)$', cf: 'Formula $x^* = \\frac{rV}{4c}$', p: 'Win probabilities $(p_1^*, p_2^*)$',
      pay: 'Payoffs $(\\pi_1^*, \\pi_2^*)$', diss: 'Rent dissipation $D$', demo: '$p_1$ at $x_1 = 60,\\ x_2 = 40$',
      warn: 'The iteration did not converge: for $r > 2$ there is no pure-strategy equilibrium.',
      tabBr: 'Best responses', tabPay: 'Expected payoff',
      zip: 'Download the Python code (.zip)', dl: 'Download figure',
    },
  }[LANG]

  const css = `
.tullock-sim{--ts-ink:#1a1a1a;--ts-soft:#6b6b6b;--ts-line:#d9d9d9;--ts-accent:#1747e6;margin:2em 0;padding:1.2em;border:1px solid var(--ts-line);font-size:.9rem;line-height:1.6}
.dark-theme .tullock-sim{--ts-ink:#e6e6e6;--ts-soft:#9a9a9a;--ts-line:#3a3a3a;--ts-accent:#5aa9ff}
.tullock-sim .ts-ctl{display:grid;grid-template-columns:auto 1fr 3.5em;gap:.3em .8em;align-items:center;margin-bottom:1em}
.tullock-sim .ts-ctl output{text-align:right;font-variant-numeric:tabular-nums}
.tullock-sim input[type=range]{width:100%;accent-color:var(--ts-accent)}
.tullock-sim .ts-tabs{display:flex;gap:1.4em;justify-content:center;border-bottom:1px solid var(--ts-line);margin-bottom:.6em}
.tullock-sim .ts-tabs button{font:inherit;padding:.3em .2em;color:var(--ts-soft);background:none;border:0;border-bottom:2px solid transparent;margin-bottom:-1px;cursor:pointer}
.tullock-sim .ts-tabs button[aria-selected=true]{color:var(--ts-ink);border-bottom-color:var(--ts-accent);font-weight:600}
.tullock-sim .ts-plot{max-width:28rem;margin:0 auto;padding-bottom:1.6rem;color:var(--ts-ink)}
.tullock-sim .ts-in{position:relative}
.tullock-sim .ts-plot svg{display:block;width:100%}
.tullock-sim .ts-plot .ts-dot{fill:var(--ts-accent)}
.tullock-sim .ts-plot .ts-lab{position:absolute;font-size:.85rem;line-height:1;white-space:nowrap}
.tullock-sim .ts-leg{position:absolute;top:2%;right:0;display:grid;grid-template-columns:auto auto;gap:.35em .5em;align-items:center;font-size:.78rem}
.tullock-sim .ts-leg svg{width:2em;height:.5em;overflow:visible}
.tullock-sim .ts-dl{display:flex;gap:.5em;align-items:center;justify-content:center;margin-top:.4em}
.tullock-sim .ts-dl button{font:inherit;padding:.2em .9em;color:var(--ts-accent);background:none;border:1px solid var(--ts-accent);cursor:pointer}
.tullock-sim .ts-dl button:hover{color:#fff;background:var(--ts-accent)}
.dark-theme .tullock-sim .ts-dl button:hover{color:#0f1b2d}
.tullock-sim .ts-dl button:disabled{opacity:.5;cursor:wait}
.tullock-sim table{width:100%;margin:1em 0 .4em;border-collapse:collapse;font-size:.88rem}
.tullock-sim td{padding:.25em .4em;border-bottom:1px solid var(--ts-line)}
.tullock-sim td:last-child{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.tullock-sim .ts-warn{color:#b3261e}
.dark-theme .tullock-sim .ts-warn{color:#ff8a80}
.tullock-sim .ts-foot{color:var(--ts-soft);font-size:.8rem}
`
  document.head.appendChild(Object.assign(document.createElement('style'), { textContent: css }))

  const NS = 'http://www.w3.org/2000/svg'
  const svgEl = (tag, attrs = {}, parent) => {
    const e = document.createElementNS(NS, tag)
    for (const k in attrs) e.setAttribute(k, attrs[k])
    if (parent) parent.appendChild(e)
    return e
  }
  const fmt = (v, d = 2) => (v === null || v === undefined ? '—' : Number(v).toFixed(d))

  // MathJax is loaded asynchronously by the page: typeset once it is there. The synchronous
  // MathJax.typeset is used on purpose: typesetPromise waits for the page's startup promise,
  // which the page config leaves pending, so it would never run.
  function typeset(node) {
    const go = () => {
      const mj = window.MathJax
      if (mj && typeof mj.typeset === 'function') {
        try { mj.typeset([node]) } catch (e) { console.error(e) }
      } else setTimeout(go, 100)
    }
    go()
  }
  const pct = (v, total) => `${(v / total) * 100}%`

  // the drawing area: an SVG for the curves, HTML spans (one per label slot) laid over it
  function makePlot() {
    const plot = Object.assign(document.createElement('div'), { className: 'ts-plot' })
    const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img' })
    const legend = Object.assign(document.createElement('div'), { className: 'ts-leg' })
    // labels are placed in percent of this inner box, so it must be exactly as tall as the SVG
    const inner = Object.assign(document.createElement('div'), { className: 'ts-in' })
    inner.append(svg, legend)
    plot.append(inner)
    let spans = {}
    let legendFor = null
    return {
      plot,
      // `fresh` drops every label slot (used when the tab changes, as ids mean different things)
      show(fig, fresh) {
        svg.innerHTML = fig.els
        if (fresh) { for (const id in spans) spans[id].remove(); spans = {} }
        const live = new Set()
        for (const l of fig.labels) {
          live.add(l.id)
          let sp = spans[l.id]
          if (!sp || sp.dataset.tex !== l.tex) {
            if (sp) sp.remove()
            sp = Object.assign(document.createElement('span'), { className: 'ts-lab', textContent: l.tex })
            sp.dataset.tex = l.tex
            inner.append(sp)
            spans[l.id] = sp
            typeset(sp)
          }
          sp.style.cssText = `left:${pct(l.x, W)};top:${pct(l.y, H)};transform:translate(${-l.ax * 100}%,${-l.ay * 100}%)`
        }
        for (const id in spans) if (!live.has(id)) { spans[id].remove(); delete spans[id] }
        if (legendFor !== fig.legend) {
          legendFor = fig.legend
          legend.replaceChildren()
          for (const e of fig.legend) {
            const s = svgEl('svg', { viewBox: '0 0 30 6' })
            svgEl('path', { d: 'M0 3H30', stroke: 'currentColor', 'stroke-width': 1.8, ...(e.dash ? { 'stroke-dasharray': '4 3' } : {}) }, s)
            legend.append(s, Object.assign(document.createElement('span'), { textContent: e.tex }))
          }
          typeset(legend)
        }
      },
    }
  }

  function mount(box) {
    const zip = (box.dataset.zip || '').replace('{lang}', LANG)
    box.replaceChildren()

    const defs = { V: [20, 100, 10, 100], c: [1, 4, 0.5, 1], r: [0.2, 3, 0.1, 1] }
    const val = {}
    const ctl = Object.assign(document.createElement('div'), { className: 'ts-ctl' })
    for (const k in defs) {
      const [lo, hi, st, v0] = defs[k]
      const lab = Object.assign(document.createElement('label'), { textContent: T[k] })
      const inp = Object.assign(document.createElement('input'), { type: 'range', min: lo, max: hi, step: st, value: v0 })
      const out = Object.assign(document.createElement('output'), { textContent: v0 })
      val[k] = v0
      inp.addEventListener('input', () => { val[k] = +inp.value; out.textContent = inp.value; schedule() })
      ctl.append(lab, inp, out)
    }

    // tabs: best responses | expected payoff
    let mode = 'br'
    const tabs = Object.assign(document.createElement('div'), { className: 'ts-tabs', role: 'tablist' })
    const tabButtons = {}
    for (const [m, text] of [['br', T.tabBr], ['pay', T.tabPay]]) {
      const b = Object.assign(document.createElement('button'), { type: 'button', textContent: text, role: 'tab' })
      b.setAttribute('aria-selected', String(m === mode))
      b.addEventListener('click', () => {
        if (mode === m) return
        mode = m
        for (const k in tabButtons) tabButtons[k].setAttribute('aria-selected', String(k === mode))
        update(true)
      })
      tabButtons[m] = b
      tabs.append(b)
    }
    const plot = makePlot()

    const warn = Object.assign(document.createElement('p'), { className: 'ts-warn', textContent: T.warn, hidden: true })
    const cells = {}
    const tbl = document.createElement('table')
    for (const k of ['eq', 'cf', 'p', 'pay', 'diss', 'demo']) {
      const tr = document.createElement('tr')
      const td = document.createElement('td')
      tr.append(Object.assign(document.createElement('td'), { textContent: T[k] }), td)
      tbl.append(tr)
      cells[k] = td
    }
    const dl = Object.assign(document.createElement('div'), { className: 'ts-dl' })
    dl.append(T.dl)
    for (const f of ['svg', 'png', 'pdf']) {
      const b = Object.assign(document.createElement('button'), { type: 'button', textContent: f.toUpperCase() })
      b.addEventListener('click', async () => {
        b.disabled = true
        try { await download(exportSvg(run(val.V, val.c, val.r), mode), mode, f) } catch (e) { console.error(e) } finally { b.disabled = false }
      })
      dl.append(b)
    }
    const foot = Object.assign(document.createElement('p'), { className: 'ts-foot' })
    foot.append(Object.assign(document.createElement('a'), { href: zip, textContent: T.zip }))
    box.append(ctl, tabs, plot.plot, dl, warn, tbl, foot)
    typeset(ctl); typeset(tbl); typeset(warn)

    function update(fresh = false) {
      const s = run(val.V, val.c, val.r)
      plot.show(FIGURE[mode](s), fresh)
      const e = s.equilibrium, ok = e.converged
      warn.hidden = ok
      cells.eq.textContent = ok ? e.x.map((v) => fmt(v)).join(', ') : '—'
      cells.cf.textContent = fmt(s.closedForm)
      cells.p.textContent = ok ? s.winProb.map((v) => fmt(v, 3)).join(', ') : '—'
      cells.pay.textContent = ok ? s.payoff.map((v) => fmt(v)).join(', ') : '—'
      cells.diss.textContent = ok ? fmt(s.dissipation, 3) : '—'
      cells.demo.textContent = fmt(s.demoWinProb, 3)
    }
    let pending = false
    function schedule() {
      if (pending) return
      pending = true
      requestAnimationFrame(() => { pending = false; update() })
    }
    update()
  }

  const init = () => document.querySelectorAll('.tullock-sim').forEach(mount)
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init)
  else init()
})()
